<?php
declare(strict_types=1);session_start();
spl_autoload_register(function(string $class):void{$prefix='MyGame\\';if(!str_starts_with($class,$prefix))return;$p=__DIR__.'/../src/'.str_replace('\\','/',substr($class,strlen($prefix))).'.php';if(is_file($p))require$p;});
use MyGame\Infrastructure\Database\Connection;use MyGame\Infrastructure\Company\DatabaseCompanyRepository;
$error=null;$_SESSION['company_csrf']??=bin2hex(random_bytes(24));$csrf=$_SESSION['company_csrf'];$repo=new DatabaseCompanyRepository(Connection::make());
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Neteisinga užklausa.');$id=$repo->create((string)$_POST['name'],(string)$_POST['city'],(string)$_POST['industry'],(float)str_replace(',','.',(string)$_POST['capital']),(string)($_POST['legal_form']??'UAB'),(string)($_POST['address']??''),(string)($_POST['manager']??''));$_SESSION['company_id']=$id;header('Location: dashboard.php');exit;}catch(Throwable$e){$error=$e->getMessage();}}
?><!doctype html><html lang="lt"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MYGAME – steigimas</title><link rel="stylesheet" href="assets/app.css"></head><body><div class="topbar"><div><b>MYGAME</b><span>Verslo simuliatorius</span></div></div><main class="page"><div class="intro"><span class="eyebrow">NAUJAS VERSLAS</span><h1>Įsteigti įmonę</h1><p>Nuo šios įmonės prasidės jūsų ekonomikos istorija.</p></div><?php if($error):?><div class="loan-alert bad"><?=htmlspecialchars($error)?></div><?php endif;?><section class="card setup-card"><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf)?>"><label>Juridinė forma<select name="legal_form"><option value="MB">MB – mažoji bendrija</option><option value="UAB" selected>UAB – uždaroji akcinė bendrovė</option></select></label><label>Įmonės pavadinimas<input name="name" maxlength="150" required placeholder="Pvz. Baltijos prekyba"></label><label>Vadovas<input name="manager" maxlength="120" required placeholder="Vardas Pavardė"></label><label>Registracijos adresas<input name="address" maxlength="180" required placeholder="Gatvė, nr., miestas"></label><label>Miestas<select name="city"><?php foreach(['Vilnius','Kaunas','Klaipėda','Šiauliai','Panevėžys'] as $city):?><option <?=($city===($_SESSION['start_city']??''))?'selected':''?>><?=htmlspecialchars($city)?></option><?php endforeach;?></select></label><label>Veikla<select name="industry"><option value="retail">Prekyba</option><option value="logistics">Logistika</option><option value="manufacturing">Gamyba</option><option value="services">Paslaugos</option></select></label><label>Steigėjo įnašas / pradinis kapitalas<input name="capital" inputmode="decimal" value="25000" required><small>MB – nuo 1 000 €, UAB – nuo 2 500 €. Ne daugiau kaip 100 000 €. Visa suma po registracijos įskaitoma į įmonės banko sąskaitą.</small></label><button class="start">Įsteigti įmonę →</button></form></section></main></body></html>